script:
(function () {
  'use strict';
  // Annual rate of return on an account with a regular deposit or withdrawal schedule between two
  // dates (plus up to two one-off amounts). Each regular payment falls on a calendar date generated
  // from the start date (weekly / every two weeks by days; monthly to yearly by calendar months,
  // clamped to month end). End-of-period timing: payments 1..N with dates on or before the end
  // date; start-of-period timing: payments 0..N-1 with dates before the end date.
  //   Ending value = B x g^T + sum D_k x g^(T - t_k), g = 1 + r, t in days / 365, T = total days / 365
  // r (effective annual) is found by bisection between sign changes on a scan grid; when there
  // are several roots the one closest to 0 is used. The nominal rate for m compounding periods a
  // year is m x (g^(1/m) - 1). "Ending value" mode evaluates the same formula at a given rate.
  // Verified (Node, scratch tests): $1,000 -> $1,100 over 365 days -> 10.00%; $10,000 -> $20,000
  //   over 3,653 days (2016-01-01..2026-01-01) -> 7.17% (2^(365/3653) - 1 = 7.1712%);
  //   $0 start, $100 a year for 10 years, $1,000 at the end -> 0.00%; $1,000 at the end of each
  //   year for 5 years, ending $5,525.63 -> 5.00% (1,000 x (1.05^5 - 1) / 0.05), and ending-value
  //   mode at 5% -> $5,526.10 (the leap day in 2024 adds a little growth);
  //   default example ($10,000 on 2021-01-01, $200 on the 1st of each month Feb 2021..Jan 2026,
  //   $25,000 on 2026-01-01) -> 3.55%, matching an independent XIRR-style solve in Python
  //   (3.5505%), monthly-compounded equivalent 3.49%; 12.6825% effective -> 12.00% compounded monthly.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var DAY = 86400000, MAX_PAYMENTS = 3200;
  var FREQ = { // [months, days] between regular payments
    weekly: [0, 7], biweekly: [0, 14], monthly: [1, 0], quarterly: [3, 0], semiannual: [6, 0], annual: [12, 0]
  };
  var COMPOUND_WORD = { 1: 'yearly', 2: 'semiannually', 4: 'quarterly', 12: 'monthly', 365: 'daily' };

  function num(id) {
    var el = document.getElementById(id);
    var v = el ? parseFloat(el.value) : NaN;
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { var el = document.getElementById(id); if (el) el.textContent = text; }
  function val(id) { var el = document.getElementById(id); return el ? el.value : ''; }
  function pctText(v) { return (Math.round(v * 10000) / 100).toFixed(2) + '%'; }
  function signed(v) { return v < 0 ? '−' + money.format(-v) : money.format(v); }

  function parseDate(s) {
    var m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s || '');
    if (!m) return null;
    var t = Date.UTC(+m[1], +m[2] - 1, +m[3]);
    return isNaN(t) ? null : t;
  }
  function addMonths(t, months) {
    var d = new Date(t), y = d.getUTCFullYear(), mo = d.getUTCMonth() + months, day = d.getUTCDate();
    var last = new Date(Date.UTC(y, mo + 1, 0)).getUTCDate();
    return Date.UTC(y, mo, Math.min(day, last));
  }
  function fmtDate(t) {
    return new Date(t).toLocaleDateString('en-US', { timeZone: 'UTC', year: 'numeric', month: 'short', day: 'numeric' });
  }

  function schedule(start, end, amount, freq, atStart) {
    var f = FREQ[freq], out = [];
    for (var k = atStart ? 0 : 1; out.length <= MAX_PAYMENTS; k++) {
      var d = f[0] ? addMonths(start, f[0] * k) : start + f[1] * k * DAY;
      if (atStart ? d >= end : d > end) break;
      out.push({ t: d, amt: amount });
    }
    return out;
  }

  // Value at time `at` (days) of the start balance and the flows dated on or before it.
  function valueAt(g, start, B, flows, at) {
    var T = (at - start) / DAY / 365, v = B * Math.pow(g, T);
    for (var k = 0; k < flows.length; k++) {
      if (flows[k].t <= at) v += flows[k].amt * Math.pow(g, T - (flows[k].t - start) / DAY / 365);
    }
    return v;
  }

  function solveRate(start, end, B, flows, E) {
    function f(r) { return valueAt(1 + r, start, B, flows, end) - E; }
    var grid = [], r;
    for (r = -0.99; r < -0.5; r += 0.05) grid.push(r);
    for (r = -0.5; r < 1; r += 0.005) grid.push(r);
    for (r = 1; r <= 20; r += 0.1) grid.push(r);
    var roots = [], prev = f(grid[0]);
    if (Math.abs(prev) < 1e-9) roots.push(grid[0]);
    for (var i = 1; i < grid.length; i++) {
      var cur = f(grid[i]);
      if (!isFinite(cur) || !isFinite(prev)) { prev = cur; continue; }
      if (cur === 0) roots.push(grid[i]);
      else if ((prev < 0) !== (cur < 0) && prev !== 0) {
        var lo = grid[i - 1], hi = grid[i], flo = prev;
        for (var it = 0; it < 80; it++) {
          var mid = (lo + hi) / 2, fm = f(mid);
          if ((fm < 0) === (flo < 0)) { lo = mid; flo = fm; } else hi = mid;
        }
        roots.push((lo + hi) / 2);
      }
      prev = cur;
    }
    if (!roots.length) return NaN;
    roots.sort(function (a, b) { return Math.abs(a) - Math.abs(b); });
    return roots[0];
  }

  function update() {
    var mode = val('rrMode');
    document.getElementById('rrEndWrap').hidden = mode !== 'rate';
    document.getElementById('rrRateWrap').hidden = mode === 'rate';
    var start = parseDate(val('rrStartDate')), end = parseDate(val('rrEndDate'));
    var B = num('rrStart'), E = num('rrEnd'), rate = num('rrRate') / 100, amt = num('rrAmount');
    var sign = val('rrDirection') === 'withdraw' ? -1 : 1;
    var freq = val('rrFreq'), atStart = val('rrTiming') === 'start', m = parseInt(val('rrCompound'), 10);
    var error = document.getElementById('rrError'), msg = '';
    var extras = [];
    for (var x = 1; x <= 2; x++) {
      var xa = num('rrExtraAmt' + x), xd = parseDate(val('rrExtraDate' + x));
      if (!isNaN(xa) && xa !== 0) {
        if (xd === null) { msg = 'Enter a date for one-off amount ' + x + '.'; break; }
        if (xa < 0) { msg = 'Enter one-off amounts as positive numbers and pick deposit or withdrawal.'; break; }
        extras.push({ t: xd, amt: (val('rrExtraType' + x) === 'withdraw' ? -1 : 1) * xa });
      }
    }
    if (!msg) {
      if (start === null || end === null) msg = 'Enter a start date and an end date.';
      else if (end <= start) msg = 'The end date must be after the start date.';
      else if ((end - start) / DAY > 366 * 100) msg = 'Use a period of 100 years or less.';
      else if (isNaN(B) || B < 0) msg = 'Enter a starting value of $0 or more.';
      else if (isNaN(amt) || amt < 0) msg = 'Enter a regular amount of $0 or more (use 0 for none).';
      else if (mode === 'rate' && (isNaN(E) || E < 0)) msg = 'Enter an ending value of $0 or more.';
      else if (mode !== 'rate' && (isNaN(rate) || rate <= -1 || rate > 1)) msg = 'Enter a yearly rate above -100% and up to 100%.';
      else if (extras.some(function (e) { return e.t < start || e.t > end; })) msg = 'One-off dates must fall between the start and end dates.';
    }
    var regular = msg ? [] : (amt > 0 ? schedule(start, end, sign * amt, freq, atStart) : []);
    if (!msg && regular.length > MAX_PAYMENTS) msg = 'That schedule has too many payments. Use a less frequent schedule or a shorter period.';
    var flows = regular.concat(extras).sort(function (a, b) { return a.t - b.t; });
    if (!msg && B === 0 && !flows.some(function (f) { return f.amt > 0; })) msg = 'Add a starting value or at least one deposit.';
    var r = NaN;
    if (!msg) {
      if (mode === 'rate') {
        r = solveRate(start, end, B, flows, E);
        if (isNaN(r)) msg = 'No rate of return between -99% and 2,000% a year matches these amounts. Check the ending value and the deposits and withdrawals.';
      } else r = rate;
    }
    error.hidden = !msg;
    error.textContent = msg;
    if (msg) return;

    var g = 1 + r, endValue = mode === 'rate' ? E : valueAt(g, start, B, flows, end);
    var deposits = 0, withdrawals = 0;
    flows.forEach(function (f) { if (f.amt > 0) deposits += f.amt; else withdrawals -= f.amt; });
    var days = Math.round((end - start) / DAY);
    var nominal = m === 365 ? 365 * (Math.pow(g, 1 / 365) - 1) : m * (Math.pow(g, 1 / m) - 1);
    set('rrMainLabel', mode === 'rate' ? 'Annual rate of return' : 'Ending value');
    set('rrMain', mode === 'rate' ? pctText(r) : money.format(endValue));
    set('rrNominal', pctText(nominal));
    set('rrNominalLabel', 'Rate compounded ' + (COMPOUND_WORD[m] || 'yearly'));
    set('rrGain', signed(endValue - B - deposits + withdrawals));
    set('rrNetAdded', signed(deposits - withdrawals));
    set('rrPeriod', (days / 365).toFixed(2) + ' years (' + days.toLocaleString('en-US') + ' days)');
    set('rrCount', regular.length + (regular.length ? ' (' + fmtDate(regular[0].t) + ' to ' + fmtDate(regular[regular.length - 1].t) + ')' : ''));
    set('rrDeposits', money.format(deposits));
    set('rrWithdrawals', money.format(withdrawals));
    set('rrEndShown', money.format(endValue));

    // Year-by-year balances at the solved (or given) rate, on each anniversary of the start date.
    var rows = [], prevT = start, prevV = B, y = 1, first = true;
    while (prevT < end && y <= 101) {
      var at = Math.min(addMonths(start, 12 * y), end);
      var inn = 0, out = 0;
      flows.forEach(function (f) {
        if ((first ? f.t >= prevT : f.t > prevT) && f.t <= at) { if (f.amt > 0) inn += f.amt; else out -= f.amt; }
      });
      var v = valueAt(g, start, B, flows, at);
      rows.push('<tr><td>' + fmtDate(at) + '</td><td>' + money.format(inn) + '</td><td>' + money.format(out) + '</td><td>' +
        signed(v - prevV - inn + out) + '</td><td>' + signed(v) + '</td></tr>');
      prevT = at; prevV = v; y++; first = false;
    }
    document.getElementById('rrYearBody').innerHTML = rows.join('');
    set('rrYearIntro', 'How the account would have grown at a steady ' + pctText(r) + ' a year, from ' + fmtDate(start) + ' to ' + fmtDate(end) + '.');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rrForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
